-- Migration 045: Russian descriptions for all standard exercises
-- UPDATE по названию — безопасно при любом порядке применения миграций.

UPDATE exercises SET description_ru = v.d
FROM (VALUES

  -- ── Грудь ────────────────────────────────────────────────────────────────
  ('Жим лёжа',                              'Базовое многосуставное упражнение на грудь. Лягте на скамью, возьмите штангу чуть шире плеч, опустите до касания груди и выжмите вверх.'),
  ('Жим гантелей лёжа',                     'Жим горизонтально с гантелями. Позволяет увеличить амплитуду движения по сравнению со штангой, хорошо растягивает грудь.'),
  ('Жим штанги на наклонной скамье',        'Наклон 30–45°, акцент на верхнюю часть груди. Держите локти под углом 75° к телу, не разводите их в стороны.'),
  ('Жим гантелей на наклонной',             'Наклонный жим с гантелями. Амплитуда шире, чем со штангой — позволяет лучше растянуть верхнюю грудь.'),
  ('Жим штанги с отрицательным наклоном',   'Скамья под углом −15–30°, акцент на нижнюю часть груди. Штанга опускается к нижней части груди.'),
  ('Жим гантелей с отрицательным наклоном', 'Нижняя грудь с гантелями. Опускайте гантели чуть ниже линии груди для максимальной растяжки.'),
  ('Жим в Смите наклонный',                 'Наклонный жим в тренажёре Смита. Фиксированная траектория снижает нагрузку на стабилизаторы.'),
  ('Жим в Смите горизонтальный',            'Горизонтальный жим в тренажёре Смита. Подходит для изолированной работы на грудь без страховщика.'),
  ('Жим в тренажёре (грудь)',               'Изолирующий жим в тренажёре. Позволяет безопасно отработать технику и добить грудь в конце тренировки.'),
  ('Разводка гантелей лёжа',                'Изолирующее упражнение. Держите лёгкий сгиб в локтях, опускайте гантели по дуге до уровня плеч, чувствуя растяжку груди.'),
  ('Разводка на наклонной скамье',          'Разводка на наклонной скамье (30–45°). Акцент на верхнюю и внутреннюю часть груди.'),
  ('Разводка на блоках',                    'Кроссовер стоя — сводите рукояти перед грудью по дуге. Позволяет менять акцент, регулируя высоту блоков.'),
  ('Кроссовер нижний блок',                 'Тяга рукоятей снизу вверх — изоляция верхней груди. Ведите руки по дуге к подбородку.'),
  ('Пек-Дек (бабочка)',                     'Изоляция грудных в тренажёре. Сводите рукояти перед грудью, сохраняя лёгкий сгиб в локтях.'),
  ('Отжимания',                             'Базовое упражнение с весом тела. Следите, чтобы тело оставалось прямым, локти уходили назад под углом 45°.'),
  ('Отжимания широким хватом',              'Широкая постановка рук увеличивает нагрузку на грудь. Опускайте грудь до касания пола.'),
  ('Отжимания с ногами на возвышении',      'Ноги на скамье или стуле. Акцент смещается на верхнюю часть груди и передние дельты.'),
  ('Отжимания на брусьях (грудь)',          'Наклонитесь вперёд под 30–40°, локти слегка в стороны. Акцент на нижнюю и среднюю грудь.'),
  ('Пуловер с гантелью',                    'Лягте поперёк скамьи, опускайте гантель за голову по дуге. Растягивает грудную клетку и широчайшие.'),
  ('Пуловер на блоке',                      'Стоя, тяните рукоять сверху вниз по дуге. Изоляция нижней части широчайших и зубчатых мышц.'),
  ('Пуловер в тренажёре',                   'Тренажёр с фиксированной траекторией для растяжки грудной клетки. Хорошо подходит для разминки.'),

  -- ── Спина ────────────────────────────────────────────────────────────────
  ('Становая тяга',                         'Главное упражнение для развития силы и массы. Держите спину прямой, тяните штангу вдоль голеней, разгибая ноги и корпус одновременно.'),
  ('Тяга верхнего блока',                   'Сидя, тяните рукоять к верхней части груди. Сводите лопатки в нижней точке, не откидывайтесь назад.'),
  ('Тяга верхнего блока за голову',         'Тяга рукояти к шее сзади. Требует хорошей подвижности плечевых суставов. Акцент на нижние широчайшие.'),
  ('Подтягивания',                          'Базовое упражнение на широчайшие. Вис на перекладине, подтягивайтесь до уровня подбородка, контролируя опускание.'),
  ('Подтягивания широким хватом',           'Хват шире плеч, тяните к верхней части груди. Максимальная нагрузка на широчайшие.'),
  ('Подтягивания обратным хватом',          'Хват снизу (супинация). Активнее подключает бицепс, широчайшие, легче для новичков.'),
  ('Подтягивания нейтральным хватом',       'Параллельный хват. Снижает нагрузку на запястья, активирует плечелучевую мышцу.'),
  ('Австралийские подтягивания',            'Горизонтальные подтягивания на низкой перекладине. Тело параллельно полу — хороший вариант для новичков.'),
  ('Тяга штанги в наклоне',                 'Наклон корпуса 45°, тяните штангу к поясу. Акцент на средние и нижние трапеции, ромбовидные.'),
  ('Тяга гантели в наклоне',               'Одноручная тяга с опорой на скамью. Позволяет растянуть широчайшую в верхней точке и хорошо сократить в нижней.'),
  ('Тяга нижнего блока сидя',              'Горизонтальная тяга к поясу сидя. Сводите лопатки в конечной точке, держите спину прямой.'),
  ('Тяга Т-грифа',                          'Тяга Т-образного снаряда к корпусу. Позволяет работать с большим весом, хорошо нагружает середину спины.'),
  ('Тяга Ятса',                             'Тяга обратным хватом в наклоне. Акцент на нижние широчайшие и бицепс.'),
  ('Тяга Пендли',                           'Тяга штанги с пола в наклоне — каждое повторение с полного останова. Развивает взрывную силу спины.'),
  ('Тяга гантелей лёжа на скамье',          'Лёжа лицом вниз, тяните гантели к поясу. Исключает читинг и инерцию.'),
  ('Фронтальная тяга сидя',                 'Тяга к верхней части груди на блоке. Акцент на верхние широчайшие, аналог подтягиваний.'),
  ('Тяга Рейдера',                          'Стоя, держитесь за опору и отклоняйтесь назад. Растяжка грудной клетки и широчайших.'),
  ('Тяга в тренажёре для спины',            'Горизонтальная тяга в тренажёре с грудным упором. Изолирует спину, убирает нагрузку с поясницы.'),
  ('Кетлбел тяга одной рукой',              'Тяга гири в наклоне одной рукой. Тренирует стабилизацию корпуса и широчайшие.'),
  ('Становая тяга трэп-штанги',             'Тяга с трапециевидным грифом. Более вертикальная траектория, меньше нагрузка на поясницу.'),
  ('Шраги со штангой',                      'Подъём плеч со штангой в руках. Изоляция верхних трапеций. Не вращайте плечами.'),
  ('Шраги с гантелями',                     'Подъём плеч с гантелями. Более естественная траектория по сравнению со штангой.'),
  ('Гиперэкстензия',                        'Разгибание корпуса на тренажёре. Укрепляет разгибатели спины и ягодицы. Не переразгибайтесь в верхней точке.'),
  ('Румынская тяга',                        'Тяга на прямых ногах от бедра. Акцент на бицепс бедра и ягодицы. Опускайте штангу вдоль ног до растяжки.'),
  ('Лодочка (Superman)',                    'Лёжа на животе, одновременно поднимайте руки и ноги. Укрепляет разгибатели спины без оборудования.'),
  ('Тяга к поясу на блоке',                 'Горизонтальная тяга стоя на нижнем блоке. Акцент на широчайшие и средние трапеции.'),

